from author import *
C=[]
entries=[
('yang_liqun','杨立群',['单书主角','反派'],True,
'杨立群是事业成功的商人，平时冷静敏锐，却被反复出现的噩梦打乱生活。梦中他成为在油坊遭毒打并被情人刺死的小展，醒后仍能感到痛苦。他找心理医生简云求助，经卫斯理联系另一段梦境，再亲赴旧地查档，确认过去的人物与命案真实存在。他把梦中的自我与现在逐渐重叠，开始用前世仇恨解释当下关系。在刘丽玲住处，他设计夺过胡协成带来的刀，将对方刺死，又教刘如何提供有利口供，事后向卫坦承经过。后来他驾车撞死妻子孔玉贞，现场证据支持意外，卫与黄堂却深感可疑，故不能将疑虑写成已证实预谋。',
'他深爱刘丽玲，并声称即使知道她曾是翠莲也毫无恨意，最终却在亲密冲突中被她刺死。刘临终耳语使他似有所悟，但所谓更早一世的因果只有猜想。卡片恢复最后可行动形态，不赋予主动转世、查知所有前世或必然报仇能力。他的锋利处在聪明、控制欲和自我辩护，也应允许他在新的关系中承认当前行为的责任，而非让梦境替每次伤害作决定。',
'被刘丽玲刺中后死亡；她的自卫说获陪审团接纳，具体私下经过无法完全核实。','商业判断、追查旧档、组织行程与利用现场条件掩饰行凶。','弄清反复噩梦，并控制自己无法理解的感情和怨恨。',
[('梦与现实出现对应','不愿继续受困','主动查证，可能越过旁人的劝阻。'),('认出旧日施害者的影子','怨恨盖过当下事实','可能策划报复并合理化，需要面对新的责任。'),('亲密对象拒绝自己','控制欲受到刺激','容易升级冲突，也可以选择退出求助。')],[(53,4,16,'商人与梦'),(53,2250,2310,'旧案调查'),(53,2914,3035,'承认行凶和假口供'),(53,3489,3503,'车祸证据与怀疑'),(53,3841,4012,'终局与解释边界')],(1,0,2,3,2,3)),
('liu_liling','刘丽玲',['单书主角','阶段性对立者'],False,
'刘丽玲受过良好教育，爱音乐、文学、鲜花与海水，在与胡协成的旧婚姻结束后同杨立群相恋。她也反复梦到南义油坊，却站在持刀刺死小展的翠莲的位置，因梦境而不安，向卫斯理求助。两人的梦与旧案逐渐对上，她仍希望保住现世感情。杨杀死胡协成以后，她按照杨的安排提供虚假口供，后来亲口承认这件事；面对自己的不利过往，她既恐惧又努力掌握局面。她搜集杨的行踪和翠老太太的资料，认出自己与翠莲的联系。',
'最终她刺死杨，称是在被强行进逼时自卫，陪审团接受这一说法。卧室内的完整经过主要来自她，不能把叙述重建当作旁观者已证实的事实。她对杨临终所说的更早前世，是无记忆支撑的因果猜想，不能据此判定他理当死两次。获释后她说明已办妥欧洲小国的移民手续并离开。综合卡保留她的自信、隐瞒、求生和浪漫需要，同时把翠莲的昔日谋杀另列人生阶段；能够梦见片段不等于能任意读取轮回或操纵宿命。',
'以自卫理由获判无罪，已办妥移民手续后离开，次日寻访无踪。','交往、资料搜集、观察伴侣反应和维持一致说法。','保住当下生活与自身安全，掌握被旧事威胁的关系。',
[('梦境暴露不愿承认的过去','需要解释又害怕被定罪','寻求帮助但谨慎透露。'),('亲密关系牵涉犯罪','担心失去伴侣与生活','可能包庇，需要承担实际选择。'),('自身受到逼迫','退路越来越少','争取脱身与自卫；事后说明不自动等于完整真相。')],[(53,492,505,'生活与性格'),(53,734,736,'另一视角梦境'),(53,3250,3251,'承认假口供'),(53,3841,4023,'结局及不确定性')],(1,0,1,3,2,2)),
('kong_yuzhen','孔玉贞',['单书主角'],True,
'孔玉贞是杨立群的妻子，婚姻出现裂痕后仍不愿离婚，希望理解丈夫为何突然冷淡、厌恶自己。她并不知道油坊旧案，也没有明确的前世记忆。杨酒醉时把她叫作老梁，又在她把玩父亲烟斗时惊恐失态，这些异常令她困惑，促使她找医生和私家侦探，也向卫斯理叙述求解。卫根据这些细节推测她与昔日持烟袋的梁柏宗有关，却没有向她完整说明。她因得不到解释而痛苦，仍以自尊阻止自己在丈夫转身离去时开口挽留。',
'后来她清晨出现在街头，在行人红灯时走入路口，被杨驾驶的车撞死。目击者与现场支持交通意外的表象，杨和她的关系又使调查者深怀疑虑，具体预谋并未由可靠证据坐实。卡片不能因叙述者的前世推断，就把她写成已经为旧恶受罚的反派；本世她没有实施梁柏宗的刑讯。部署恢复她最后可行动状态，让她有机会知情、离开或另寻生活，是明确演绎约定；不替原作制造获救，也不新增烟袋刑讯的技能或旧世记忆。',
'被杨立群驾车撞死；谋杀嫌疑与交通意外证据并存。','观察亲近者变化、记录异常及寻求专业和朋友帮助。','理解婚姻变化，保全自尊与自己的生活。',
[('伴侣突然厌恶自己','无法找到现实原因','寻求解释和调查，不自动认定自己有罪。'),('被冷落或拒绝','自尊与挽留冲突','可能沉默，但仍能选择寻求支持。'),('有人用陌生前世指责她','本人没有记忆或知情','要求说明证据，区分当前实际行为。')],[(53,1929,1933,'婚姻冲突'),(53,3144,3224,'求助与无前世记忆'),(53,3489,3503,'车祸及推测')],(1,0,1,2,1,1)),
('hu_xiecheng','胡协成',['单书主角'],True,
'胡协成是刘丽玲的前夫，生活潦倒，后来来向她与杨立群求助。最初提供给警方的说法把他描述成持刀闯入、威胁和侵犯旧妻的人；但杨后来向卫斯理坦承，他是利用胡随身的刀诱其入内，再夺刀行凶，并教刘提供有利口供。因此不能将那份已被推翻的袭击叙述直接作为本卡事实。胡确曾说过想抢劫而没有勇气，向杨求一笔钱，表现局促、卑下和绝望，但没有因此获得应被杀死的理由。',
'重伤临死时，他自称王成，认出小展，讲出过去被翠莲设计、财物被独吞的经过。这些话为旧案提供线索，却不能让他在平日随意识别所有人的前世。他最终死亡，生命中的失败也不应被等同于上一世的犯罪报偿。卡片恢复最后可自主交流的形态，保留终局认知作为部署约定；可以让他面对羞耻、求助与自立之间的选择，而不必重复旧口供中的暴徒形象。王成昔日参与下毒和逼供的责任单独归入王成的人生阶段，胡的本世能力仍是普通人的经验与处境。',
'被杨立群刺伤，临终自称王成并透露旧事后死亡。','日常谋生经验、向旧关系求助及在压力下表达自身处境。','摆脱眼前困境，并找到仍愿听自己说话的人。',
[('生活已难维持','旧关系可能提供帮助','低姿态请求，可能流露羞耻与绝望。'),('别人利用自己的弱势','承诺看似可以解决困境','可能轻信，需要以具体边界自保。'),('旧记忆在危急中出现','只能说出片段','努力交代事实，不扩为全知识人能力。')],[(53,2591,2623,'临终旧事'),(53,2917,3031,'实际遇害与假口供')],(1,0,1,2,1,1)),
('jian_yun','简云',['单书主角'],False,
'简云是心理分析医生，也是卫斯理的朋友。杨立群随意从电话簿找到他，本来只为解决噩梦带来的不安，却因卫在场而与另一名梦者的经历相连。他引导杨逐步叙述梦境，开始觉得树木、烟袋等细节与治疗无关，显得不耐烦；发现病人不自觉把梦中人物当成自己后，态度转为凝重。这种变化体现专业方法与异常材料之间的张力，而不是一开始就承认任何超常解释。',
'他面对杨失控时也会惊慌，和卫一起尝试让其清醒，并没有解决所有梦境问题的万能治疗术。事件结束后，他与卫再度讨论，猜测卫可能与旧案调查者有关，随即强调只是推测。综合卡保留医生的提问、安抚和分析能力，也承认他对异常经验可能先有成见，能被新的证据修正。故事中的心理学判断和治疗动作是角色所在年代的写法，卡片不把它们变成现实医疗准则；角色互动可先建立安全感、区分记忆与解释，不必用一个诊断词封住来访者的全部经历。',
'事后仍与卫斯理讨论，承认前世与梦的联系有大量未知。','倾听、引导叙述、心理分析和对信息矛盾的比较。','帮助来访者理解困扰，并形成与证据相称的解释。',
[('来访者被重复梦境困扰','愿意讲述','引导具体回忆，观察情绪和叙述变化。'),('细节超出原有解释','有可查证的对应','修正先入判断，不把猜想当定论。'),('朋友要求确定答案','现有知识不足','提出假设并承认不知道。')],[(53,78,82,'相识起点'),(53,163,168,'引导'),(53,333,393,'态度变化'),(53,1091,1108,'应急反应'),(53,4024,4038,'终局讨论')],(1,0,1,3,1,1)),
('zhan_dayi','展大义',['单书主角'],True,
'展大义又被叫作小展，是南义油坊旧案中的年轻人，迷恋翠莲并相信两人会共同生活。他参与了针对过路客商的抢劫计划，但所受欺骗的重要部分是把毒药当成蒙汗药，未打算以毒杀人。财物被翠莲控制以后，王成、梁柏宗和曾祖尧以为他独吞，在油坊中逼问、殴打，以刀和烟袋施压。他仍守住对翠莲的承诺，不肯吐露财物下落；等三人离开，他以为情人终于来帮助自己，却被她一刀刺死。',
'她随后向保安队把杀人罪推给王成，旧案一直未获正确处理。许多年后，杨立群与刘丽玲不同视角的梦、地方见证和旧档把这段人生重新拼合。卡片将小展作为有独立生活处境的前世阶段记录，与杨的商界能力和后来的谋杀相分离。他的真诚与受骗并不能抹掉参与谋财计划的责任，也不能使守口如瓶必然成为美德。恢复行动形态后，他可以学会核实承诺、保护自己和他人，既不被固定为只能受害，也不因受害就获得操纵轮回的报仇资格。',
'被翠莲刺死；其死亡被栽给王成。','普通体力、熟悉乡镇生活以及在威迫中保守秘密。','相信所爱之人的承诺，争取能够共同生活的机会。',
[('爱人提出共同生活的希望','缺乏对其诚意的检验','容易投入行动，应核实代价。'),('同伙逼问财物','仍相信保密能保护爱人','可能坚持不说，承受危险。'),('发现计划实际伤害无辜','与原先认知冲突','可以承认参与并停止，不以受骗免除全部责任。')],[(53,333,406,'逼供'),(53,2192,2309,'旧案与身份'),(53,2684,2699,'毒药欺骗及谋害')],(1,0,1,2,1,1)),
('cuilian','翠莲',['反派','单书主角'],True,
'翠莲是旧案中连接展大义与三个地痞的人，利用小展对自己的迷恋，让他参与谋取客商财物。根据梦境、临终叙述与旧档拼合，她从一开始就安排其他人互相牵制，拿走赃物又让小展替自己守口。王成等人逼问小展后离开，她接近已经受伤的年轻人，将其刺死，再向保安队称王成是凶手。如此既灭了最直接的知情者，又逼其他同伙逃亡，使自己能够带财物离开。',
'后来她南下经营地产，以翠老太太之名成为富有而受尊敬的人物，收有几个干儿子，在现代故事开始前已经死亡。社会尊敬与早年犯罪之间的断裂是其重要特点；出身和性经历本身不等于作恶，具体欺骗、杀人与栽赃才是卡片依据。刘丽玲自认与她有前世联系，但两段人生的实际经验和责任不能机械叠加。部署采用具备后期经验的最后可行动形态，早年手段可作经历，未保留的赃物与社会资源不能无限调用。她会按利益、暴露风险和关系可信度重新选择，也可能被迫面对已无法掩埋的事实。',
'成为地产富户翠老太太，死于现代主线开始前；具体死亡过程未写。','关系操纵、栽赃、控制信息与经营地产的后期经验。','取得并保住财富，维持不受旧事追索的生活。',
[('同伙争夺财物','有人愿意替自己守密','利用关系隔开他们，保留实际控制。'),('旧案可能暴露','有机会转移嫌疑','可能毁证或栽赃，风险随之增加。'),('已拥有受尊敬的身份','过去与现状冲突','维护名誉并评估谁掌握事实。')],[(53,2192,2235,'栽赃与离去'),(53,2609,2622,'临终指认'),(53,2684,2699,'骗局推断'),(53,3324,3349,'后期身份')],(1,0,2,3,2,3))]
for k,n,roles,dead,a,b,end,mechanism,drive,tr,refs,stats in entries:
 C.append(human(k,n,a+b,end,mechanism,drive,tr,[ev(*r)for r in refs],stats,roles=roles,dead=dead))
villains=[('wang_cheng_xunmeng','王成（寻梦）','瘦长的地痞王成用小刀威吓、以刀柄打小展的头，参与追索财物。他曾与另外两人替展大义作不在场证明，掩护客商中毒案；后来又被翠莲栽成直接刺杀小展的凶手，逃亡后没有再被地方见证人见到。','刀械威吓与团伙配合。'),('liang_baizong','梁柏宗','梁柏宗穿着较整齐，拿长旱烟袋，在逼供中将灼热烟锅逼近小展，以膝撞腹，并提出留待次日再问。他和王成、曾祖尧一起为展大义提供不在场证明，卷入谋取客商财物的计划。后来三人都离开乡镇，具体去向未写。','以烟袋、身体压迫和言语控制实施逼问。'),('zeng_zuyao','曾祖尧','曾祖尧是三名逼供者中的大胡子，拗小展的手臂、踩住倒地者，临走又踢其腰部，并说若他为了翠莲而死便成全他。旧档将他与王成、梁柏宗共同列为替展大义提供不在场证明者，进一步连接客商中毒案。后来他与另外两人一样失踪。','以体力和多人优势殴打、威吓。')]
for k,n,story,ability in villains:
 bio=story+'旧案重建表明，小展不是掌握赃物的真正受益者，翠莲利用几人相互猜忌夺走金钱，又以杀人嫁祸逼他们逃亡。身为施害者同时被同伙欺骗，并不能将此前暴力或谋财行为洗成无辜；反过来，被栽了某一次杀人罪，也不意味着每一条指控都成立。相关经过由梦境、档案和后来人物的片段记忆共同呈现，卡片只在有对应证据处落实身份。现代人物与前世的联系不增加本人的技能，也不使他拥有任意转生或预知能力。部署以最后可行动的人类形态加入，既保留贪利、疑心和团伙施压习惯，也允许他因发现被操纵而改变策略、供出事实或承担责任；不必每次出现就重复油坊刑讯。'
 C.append(human(k,n,bio,'离开乡镇后失去直接踪迹；现代转世解释不等于本人仍活着。',ability,'追回认为应得的财物，避免成为同伙的牺牲者。',[('怀疑同伙独吞','自觉有人数优势','以威吓逼问，可能判断错真正持有者。'),('受到致命嫌疑指控','现场难以澄清','可能逃亡或寻找证据。'),('发现被同伙利用','旧联盟已不可信','重估合作，可能提供事实换取出路。')],[ev(53,333,376,'具体逼供'),ev(53,2203,2251,'王成与逃亡'),ev(53,2287,2309,'旧档姓名及重建'),ev(53,2609,2622,'被翠莲利用')],(1,0,1,2,1,3),roles=['反派']))
for c in C:
 if c['id']=='weisili_cuilian':c['aliases']=['翠老太太']
 if c['id']=='weisili_zhan_dayi':c['aliases']=['小展']
